/**
 * Postinstall script to generate the Prisma client.
 *
 * Runs the Prisma CLI that is installed for this package. The CLI used to be
 * looked up at <repo root>/node_modules/.bin/prisma, which exists with Yarn's
 * hoisting but not with pnpm (the binary lives in this package's own
 * node_modules), so on pnpm the generate step failed on every install and the
 * client had to be generated by hand.
 */

const path = require('path');
const { execFileSync } = require('child_process');

const schemaPath = path.resolve(__dirname, '../prisma/schema.prisma');

console.log('🔄 Postinstall: Generating Prisma client...');

try {
  // Resolve the CLI's entry point from this package, whatever the package manager's layout.
  const prismaCli = require.resolve('prisma/build/index.js', { paths: [path.resolve(__dirname, '..')] });

  execFileSync(process.execPath, [prismaCli, 'generate', `--schema=${schemaPath}`], {
    cwd: path.resolve(__dirname, '..'),
    stdio: 'inherit',
    env: {
      ...process.env,
      PRISMA_GENERATE_SKIP_AUTOINSTALL: 'true',
    },
  });

  console.log('✅ Prisma client generated successfully!');
} catch (error) {
  console.warn('⚠️  Prisma client generation failed in postinstall:', error.message);
  console.warn('   Generate it manually: pnpm --filter @ahava-healthcare/api prisma:generate');
  // Don't fail the install process
  process.exit(0);
}
